<?php namespace App\Services; use App\Repositories\PagamentoRepository; class PagamentoService { public function __construct(private PagamentoRepository $repo,private ClienteService $clientes,private AuditoriaService $audit) {} public function create(array $data):array {$c=$this->clientes->owned($data['cliente_id']);abort_unless($c,404);$before=$this->clientes->balance($c['id']);$p=$this->repo->create(array_merge($data,['loja_id'=>session('loja_id'),'usuario_id'=>session('usuario_id')]));$this->audit->log('Pagamento registrado','pagamento',$p['id'],'Pagamento de R$ '.number_format($p['valor'],2,',','.'));return [$p,$before,$before-(float)$p['valor']];} }
